        url = so + '/user/user/login.html,';
        body = `username=${info.用户名}&password=${pwd}&code=${java.getVerificationCode(imgurl)}`;
    } else {
    	code=String(info.邮箱验证码)||java.getVerificationCode(sentEmail(info.邮箱))
        url = so + '/qs_register_go.php,';
        body = `name=${info.用户名}&email=${info.邮箱}&invite_code=${info.邀请码}&password=${pwd}&repassword=${pwd}&email_code=${code}`;
